import{_ as t,o as n,c as r,a4 as i}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0021 — Termes de taxonomie : un registre par site, dérivé des contenus, introduit par la règle de propagation","description":"Extrait de docs/adr/0021-termes-de-taxonomie-registre-par-site.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0021 — Termes de taxonomie : un registre par site, dérivé des contenus, introduit par la règle de propagation","description":"Extrait de docs/adr/0021-termes-de-taxonomie-registre-par-site.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0021-termes-de-taxonomie-registre-par-site.md","filePath":"developpeurs/adr/0021-termes-de-taxonomie-registre-par-site.md"}'),s={name:"developpeurs/adr/0021-termes-de-taxonomie-registre-par-site.md"};function o(a,e,l,c,d,u){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0021--termes-de-taxonomie--un-registre-par-site-dérivé-des-contenus-introduit-par-la-règle-de-propagation" tabindex="-1">ADR-0021 — Termes de taxonomie : un registre par site, dérivé des contenus, introduit par la règle de propagation <a class="header-anchor" href="#adr-0021--termes-de-taxonomie--un-registre-par-site-dérivé-des-contenus-introduit-par-la-règle-de-propagation" aria-label="Permalink to &quot;ADR-0021 — Termes de taxonomie : un registre par site, dérivé des contenus, introduit par la règle de propagation {#adr-0021--termes-de-taxonomie--un-registre-par-site-dérivé-des-contenus-introduit-par-la-règle-de-propagation}&quot;">​</a></h1><p><strong>Date :</strong> 21 août 2026 <strong>Statut :</strong> Accepté avec garde-fou <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §9.2, règle 6 de la propagation ; Epic E10, plan d&#39;action §12.5 et §12.8</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>La sixième des sept règles de propagation du CDC énonce :</p><blockquote><p>Un terme de taxonomie poussé est <strong>créé sur B s&#39;il n&#39;existe pas, sinon fusionné</strong> avec l&#39;existant.</p></blockquote><p>et le plan d&#39;action (§12.5, §12.8) ajoute la contrainte qui compte : <em>« cas de conflit de slug testé explicitement, avec une UX de résolution — pas une fusion silencieuse non tracée »</em>.</p><p>Or, avant l&#39;Epic E10, <strong>il n&#39;existait aucune entité « terme de taxonomie » dans ce dépôt.</strong> Recherche exhaustive faite : un terme est une chaîne de caractères, rangée à deux endroits, et nulle part ailleurs.</p><ol><li>Dans <code>content_entries.data</code> (E1), comme valeur d&#39;un champ <code>multi_select</code> dont le Content Type déclare les options. Le Content Engine ne réserve aucun nom de champ (CDC §3.2) : c&#39;est une convention, <code>taxonomies</code>, que la <code>ContentSource</code> (E2) et le Listing Engine (E3) lisent par défaut.</li><li>Dans <code>search_index.taxonomies</code> (E13, <code>TEXT[]</code>), recopié à l&#39;indexation pour alimenter la facette « rubrique ».</li></ol><p>Aucune table, aucun identifiant, <strong>aucun slug</strong>. La règle 6 est donc, littéralement, inapplicable en l&#39;état : « créer le terme sur B » n&#39;a pas de sens si un terme n&#39;a d&#39;existence que dans les contenus qui l&#39;emploient, et « conflit de slug » n&#39;en a pas davantage s&#39;il n&#39;existe pas de slug.</p><p>Deux options étaient défendables, et le brief de l&#39;Epic les posait explicitement.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Introduire une table <code>taxonomy_terms</code>, scopée par site, alimentée à l&#39;usage, et strictement bornée à ce que la règle 6 exige.</strong></p><p>Cinq propriétés portent la décision, et la troisième est le garde-fou.</p><ol><li><p><strong>Le registre est par site, jamais par organisation.</strong> C&#39;est ce qui donne un sens à la règle : « le terme existe-t-il déjà <strong>sur B</strong> ? » est une question dont la réponse peut être non. Un registre au niveau de l&#39;organisation y aurait toujours répondu oui, et la règle 6 serait redevenue décorative — exactement le défaut que ce dépôt évite ailleurs sous le nom de « réglage qui ne fait rien ».</p></li><li><p><strong>Le slug est dérivé du libellé, jamais saisi</strong>, par <code>tokenize</code>/<code>normalize</code> (<code>app/search/normalize.py</code>) — <strong>la même</strong> fonction de repliage que la recherche (ADR-0016). « Vie Associative », « vie associative » et « Vie associative » donnent <code>vie-associative</code> ; « Écoles » et « Ecoles » donnent <code>ecoles</code>. C&#39;est ce repliage partagé qui fait que « fusionner » veut dire quelque chose : deux repliages différents auraient produit des termes qui se confondent à l&#39;indexation mais pas à la propagation, et l&#39;écart ne se serait vu qu&#39;à l&#39;usage.</p></li><li><p><strong>Garde-fou : les contenus ne référencent pas cette table.</strong> Aucune clé étrangère, aucune réécriture d&#39;E1, d&#39;E3 ni d&#39;E13. Les enregistrements continuent de porter leurs termes comme des chaînes, les vues liste continuent de filtrer par containment JSONB, la facette continue de lire <code>search_index.taxonomies</code>. La table est un <strong>registre de provenance et d&#39;existence</strong>, pas la source de vérité du contenu. C&#39;est la limite explicite du périmètre : E10 n&#39;ouvre pas un module de gestion de taxonomie (arborescence de rubriques, renommage global, fusion de vocabulaires), qui est hors CDC pour cet Epic.</p></li><li><p><strong>Le registre se remplit à l&#39;écriture d&#39;un contenu</strong>, pas par une saisie préalable (<code>ensure_local_terms</code>, appelé par les routes d&#39;écriture d&#39;enregistrement). Exiger de déclarer une taxonomie avant de l&#39;employer aurait ajouté une étape que le Content Engine n&#39;impose pas — et aurait rendu la mutualisation dépendante d&#39;un travail de préparation que personne n&#39;aurait fait.</p></li><li><p><strong>Trois issues nommées, une seule silencieuse.</strong> Terme absent → <strong>créé</strong>, avec sa provenance (<code>origin_id</code>, <code>origin_site_id</code>). Terme présent avec le même libellé → <strong>fusionné</strong>, sans arbitrage : ce sont deux écritures du même terme, il n&#39;y a rien à décider. Même slug, libellé différent → <strong>conflit</strong>, inscrit dans <code>content_replication.conflicts</code>, listé par <code>GET /replication/conflicts</code> et levé seulement par <code>POST /replication/{id}/conflicts/resolve</code>. Le libellé du site d&#39;accueil n&#39;est <strong>jamais</strong> modifié sans cet arbitrage, et une synchronisation qui repasse ne vide pas la liste des conflits.</p></li></ol><p><strong>Deux stratégies d&#39;arbitrage, et pas une troisième</strong> : <code>keep_target</code> (le site d&#39;accueil garde son libellé) et <code>take_source</code> (il adopte celui de la source). Le troisième réflexe — renommer pour obtenir deux termes distincts — supposerait de réécrire les valeurs de taxonomie <em>dans les enregistrements déjà répliqués</em>. C&#39;est une opération de gestion de taxonomie ; l&#39;implémenter à moitié ici laisserait des contenus pointant vers un terme qui n&#39;existe plus, ce qui est pire que le conflit qu&#39;on prétendait résoudre.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Correspondance de chaînes normalisées, sans nouvelle table</strong> (repliage casse/accents à la volée, comme la recherche)</td><td>Défendable, et c&#39;était l&#39;option la plus légère. Mais elle rend la règle 6 <strong>inobservable</strong> : « créé sur B » devient un non-événement (une chaîne existe partout où on l&#39;écrit), et « conflit de slug » se réduit à « deux contenus n&#39;écrivent pas le terme pareil » — sans lieu où inscrire le conflit, sans rien à présenter à l&#39;arbitrage, donc sans l&#39;UX de résolution que le CDC exige nommément. Le plan d&#39;action classe la fusion silencieuse parmi les risques de l&#39;Epic (§12.8) ; cette option n&#39;aurait offert aucun moyen de la mitiger.</td></tr><tr><td><strong>Une entité de taxonomie complète</strong> (vocabulaires, arborescence, traductions, fusion globale, réécriture des contenus)</td><td>Hors périmètre CDC pour E10 et disproportionné : la règle 6 n&#39;exige ni hiérarchie, ni renommage global. Construire le module entier maintenant aurait fait porter à cet Epic des décisions (que devient un contenu quand son terme parent est supprimé ?) qu&#39;aucune ligne du CDC ne tranche.</td></tr><tr><td><strong>Normaliser les termes dans <code>content_entries.data</code></strong> (remplacer les chaînes par des identifiants)</td><td>Migration de données sur tout le parc, réécriture des filtres de liste (E3), de la facette (E13) et des sources de blocs (E2), pour un bénéfice nul du point de vue de la règle 6. C&#39;est le genre de refonte qu&#39;on justifie par un besoin fonctionnel, pas par une règle de propagation.</td></tr><tr><td><strong>Déduire les termes du schéma du Content Type</strong> (les <code>options</code> du champ <code>multi_select</code>)</td><td>Un Content Type appartient à l&#39;<strong>organisation</strong> : ses options sont donc identiques sur tous les sites par construction, et « le terme existe-t-il sur B ? » redevient toujours vrai. En prime, cela aurait fait dépendre la propagation d&#39;une modification de schéma — c&#39;est-à-dire d&#39;un incrément de <code>schema_version</code>, donc du verrou de cohérence, donc d&#39;un blocage à chaque nouveau terme.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>La règle 6 est <strong>observable et testée dans les deux sens</strong> : création, fusion, conflit et arbitrage explicite (<code>test_regle_6_…</code>, <code>apps/api/tests/test_multisite.py</code>).</li><li>Le conflit vit sur la ligne de réplication, à côté du contenu qui l&#39;a provoqué : un agent voit <em>quel contenu</em> a déclenché <em>quel désaccord de libellé</em>, et pas seulement qu&#39;un désaccord existe quelque part.</li><li>L&#39;usine à sites obtient un sens précis pour <code>share: [taxonomies]</code> (CDC §9.3) : les termes du site modèle sont repris <strong>avec leur provenance</strong>, donc reconnus comme les mêmes termes lors des propagations suivantes, au lieu d&#39;ouvrir un conflit sur des homonymes que l&#39;usine venait elle-même de créer.</li><li>Le repliage partagé avec la recherche évite la classe de bogues « le terme se retrouve mais ne se fusionne pas ».</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Deux représentations d&#39;un terme coexistent</strong> : la chaîne dans le contenu et la ligne dans le registre. Elles peuvent diverger — renommer un libellé dans le registre ne renomme rien dans les contenus. C&#39;est assumé et borné : le registre ne sert qu&#39;à la propagation, et rien dans le rendu public ne le lit. Le jour où un module de taxonomie sera ouvert, c&#39;est lui qui devra trancher la synchronisation des deux, et cette ADR sera remplacée.</li><li>Le registre ne se purge pas : un terme cesse d&#39;être employé par tous les contenus d&#39;un site sans disparaître de la table. Un balayage de nettoyage serait facile à écrire, mais il supprimerait aussi la trace d&#39;un terme volontairement conservé — le silence est ici moins coûteux qu&#39;une suppression automatique.</li><li>Une écriture de contenu fait désormais une lecture par terme distinct. Le coût est borné (quelques termes par enregistrement, sur une clé unique), et l&#39;écriture de contenu est déjà transactionnelle avec l&#39;indexation.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] <code>taxonomy_terms</code> (<code>apps/api/app/models/multisite.py</code>), migration <code>0014_multisite_propagation</code>.</li><li>[x] <code>app/multisite/taxonomy.py</code> — <code>slugify</code>, <code>ensure_local_terms</code>, <code>push_terms</code>, <code>resolve_conflict</code>.</li><li>[x] Conflits portés par <code>content_replication.conflicts</code>, listés et arbitrés par <code>app/api/multisite.py</code>.</li><li>[x] Recette : <code>test_regle_6_un_terme_pousse_est_cree_puis_fusionne_et_le_conflit_est_arbitre</code>.</li><li>[x] Admin (Nuxt, hors périmètre backend) : écran d&#39;arbitrage des conflits, alimenté par <code>GET /replication/conflicts</code>. → <strong>Close</strong> par <code>7638d60</code> (28/08/2026) : <code>apps/admin/pages/multisite/conflits.vue</code> liste les conflits (l.47, <code>GET /api/replication/conflicts</code>) et les résout (l.77-110) par le BFF <code>server/api/replication/conflicts/[id]/resolve.post.ts</code>, qui appelle <code>POST /api/v1/replication/{id}/conflicts/resolve</code>. Cochée le 26/09/2026 (audit du 26/09, SUIVI-3).</li><li>[ ] Si un module de gestion de taxonomie est ouvert un jour, il devra trancher la relation entre le registre et les chaînes portées par les contenus — et remplacer cette ADR.</li></ul>',24)])])}const g=t(s,[["render",o]]);export{m as __pageData,g as default};
